'use strict';
const SUBJECTS={'101':{name:'思想政治理论',short:'政治',desc:'原理判断、材料分析与时政联系',structure:'16 单选 × 1 ＋ 17 多选 × 2 ＋ 5 分析 × 10'},'201':{name:'英语（一）',short:'英语一',desc:'阅读逻辑、语言运用与书面表达',structure:'完形 10 ＋ 阅读 40 ＋ 新题型 10 ＋ 翻译 10 ＋ 写作 30'},'706':{name:'中国语言文学综合知识',short:'综合知识',desc:'名词解释准确，跨学科简答有据',structure:'16 名词解释 × 5 ＋ 7 简答 × 10'},'808':{name:'中国语言文学专业基础',short:'专业基础',desc:'从概念辨析走向文本细读与论证',structure:'6 名词解释 × 5 ＋ 4 简答 × 15 ＋ 1 论述 × 60'}};
let xiaoPaperIndex=0,xiaoPageIndex=0;
let hotspotCategory='全部';
const KEY='kaoyan-studio-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={version:1,attempts:[],marks:{},notes:{}},view='home',subject='101',active=null,idx=0,reveal=false,filter='all';
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.version===1&&Array.isArray(saved.attempts))state=saved;}catch(e){console.warn('Saved state unavailable',e);}
state.marks=state.marks||{};state.notes=state.notes||{};state.xiao8=state.xiao8||{};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN');}catch(e){$('#save-status').textContent='保存失败，请导出备份';}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600);}
function paper(id){return BANK.find(p=>p.id===id)||XIAO8.find(p=>p.id===id)}
function attemptPaper(a){return a.bankVersion===2?paper(a.paper):(LEGACY_BANK.find(p=>p.id===a.paper)||paper(a.paper));}
function questions(a){const p=attemptPaper(a);return a.ids.map(id=>p.questions.find(q=>q.id===id)).filter(Boolean)}
function answered(a,q){const v=a.answers[q.id];return Array.isArray(v)?v.length>0:typeof v==='string'&&v.trim().length>0;}
function correct(a,q){return JSON.stringify([...(a.answers[q.id]||[])].sort())===JSON.stringify([...(q.answer||[])].sort());}
function markKey(p,q){return p.id+'/'+q.id;}
function earned(a,q){if(q.type!=='essay')return correct(a,q)?q.points:0;return (a.ratings[q.id]||[]).reduce((sum,i)=>sum+(q.rubric?.[i]?.points||0),0)}
function summary(a){const qs=questions(a);return {score:qs.reduce((s,q)=>s+earned(a,q),0),max:qs.reduce((s,q)=>s+q.points,0),done:qs.filter(q=>answered(a,q)).length,subjective:qs.filter(q=>q.type==='essay').length,reviewed:qs.filter(q=>q.type==='essay'&&Object.hasOwn(a.ratings,q.id)).length};}
function remaining(a){return a.deadline?Math.max(0,Math.ceil((a.deadline-Date.now())/1000)):a.remaining;}
function fmt(t){return String(Math.floor(t/3600)).padStart(2,'0')+':'+String(Math.floor(t/60)%60).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function nav(){ $('#subjects').innerHTML=Object.entries(SUBJECTS).map(([code,s])=>`<button data-subject="${code}" class="${subject===code&&view!=='home'?'active':''}"><b>${code}</b>${s.short}<small>${s.name}</small></button>`).join('');}
function show(v){view=v;active=null;reveal=false;render();window.scrollTo(0,0);}
function start(pid,mode,ids){const p=paper(pid),a={id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),paper:pid,bankVersion:2,mode,ids:ids||p.questions.map(q=>q.id),answers:{},ratings:{},remaining:p.minutes*60,deadline:null,status:'working',created:Date.now(),position:0};if(mode==='exam')a.deadline=Date.now()+a.remaining*1000;state.attempts.unshift(a);active=a;idx=0;view='exercise';subject=p.subject;save();render();window.scrollTo(0,0);}
function resume(id){active=state.attempts.find(a=>a.id===id);if(!active)return;idx=Math.min(active.position||0,questions(active).length-1);subject=paper(active.paper).subject;view='exercise';reveal=false;render();}
function home(){const n=BANK.reduce((s,p)=>s+p.questions.length,0),done=state.attempts.filter(a=>a.status==='submitted').length;return `<p class="eyebrow">FOUR SUBJECTS · ONE STUDY ROOM</p><h1>把每一次练习，变成下一次得分。</h1><p class="subtitle">选一科，开始一套卷。先独立作答，再核对依据，把薄弱处留给下一次练习。</p><section class="hero"><h2>从知识储备，到考场表达</h2><p>整卷计时模拟 · 专项练习 · 逐项自评 · 错题复盘</p><div class="stats"><div><b>${BANK.length}</b><span>套原创模拟卷</span></div><div><b>${n}</b><span>道练习题</span></div><div><b>${done}</b><span>次已交卷练习</span></div></div></section><div class="cards">${Object.entries(SUBJECTS).map(([code,s])=>`<section class="card"><span class="tag">${code} · ${code==='706'||code==='808'?150:100} 分</span><h2>${s.name}</h2><p>${s.desc}</p><p class="muted">${s.structure}</p><button class="btn" data-subject="${code}">进入${s.short}</button></section>`).join('')}</div><div class="note">按近期材料构建的原创模拟卷。专业课回忆资料的缺项、808A适用范围和时政来源，见“命题依据与资料”。练习分数不等同于正式阅卷分数。</div>`;}
function subjectPage(){const s=SUBJECTS[subject],ps=BANK.filter(p=>p.subject===subject),topics=[...new Set(ps.flatMap(p=>p.questions.map(q=>q.topic)))];return `<p class="eyebrow">SUBJECT ${subject}</p><h1>${s.name}</h1><p class="subtitle">${s.desc}。每套 ${ps[0]?.total||0} 分，整卷建议 180 分钟。</p><div class="note">${s.structure}${subject==='101'?'<br>完整政治卷另含思想道德与法治、形势与政策及当代世界经济与政治，保留真题考试范围。':''}</div>${subject==='101'?'<section class="card"><h2>时政与周年专题</h2><p>会议与文件、发展时间轴、周年事件，逐项连接教材原理与材料分析。</p><button class="btn" data-view="hotspots">进入专题</button><button class="btn secondary" data-view="xiao8">肖八原卷 · 8套</button></section>':''}<div class="cards">${ps.map(p=>{const last=state.attempts.find(a=>a.paper===p.id&&a.status==='working');return `<section class="card"><span class="tag">原创模拟</span><span class="tag">${p.questions.length} 题 · ${p.total} 分</span><h2>${esc(p.title)}</h2><p class="muted">${esc(p.basis)}</p><div class="actions"><button class="btn" data-start="${p.id}" data-mode="exam">整卷模拟</button><button class="btn secondary" data-start="${p.id}" data-mode="practice">自由练习</button>${last?`<button class="btn secondary" data-resume="${last.id}">继续上次</button>`:''}</div></section>`}).join('')}</div><section class="card" style="margin-top:22px"><h2>按考点练习</h2><p class="muted">随机选择本学科一套含该考点的试卷，抽取对应题目，保留原题分值。专项练习不冒充整卷。</p><div class="filter"><label>考点 <select id="topic">${topics.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><button class="btn" id="topic-start">开始专项</button><button class="btn secondary" id="random-start">随机练 5 题</button></div></section>`;}
function exercise(){const a=active,p=attemptPaper(a),qs=questions(a),q=qs[idx],v=a.answers[q.id],locked=a.status==='submitted',allowed=!p.original&&(locked||a.mode!=='exam'),shown=!p.original&&(locked||reveal),k=markKey(p,q),ss=summary(a);return `<div class="topline"><div><p class="eyebrow">${a.mode==='exam'?'限时整卷':a.mode==='topic'?'专项练习':'自由练习'} · ${locked?'已交卷':'作答中'}</p><h1 style="font-size:28px">${esc(p.title)}</h1></div><button class="btn secondary" data-view="${p.original?'xiao8':'subject'}">${p.original?'返回肖八':'返回科目'}</button></div>${a.bankVersion!==2?'<p class="note">这是更新前创建的答卷，保留原题和原评分。新练习使用修订后的题库。</p>':''}${locked?`<section class="card"><div class="topline"><div>${p.original?`<h2>答卷已保存</h2><p>已作答 ${ss.done} / ${qs.length} 题 · 原卷不评分</p>`:`<span class="score">${ss.score} / ${ss.max}</span><p class="muted">客观题自动计分；主观题自评 ${ss.reviewed}/${ss.subjective} 题。${ss.reviewed<ss.subjective?'未自评部分暂计 0 分。':'这是自评合计。'}</p>`}</div><button class="btn secondary" id="export-attempt">导出本次答卷</button></div></section>`:''}<div class="layout"><div><section class="card"><div class="topline"><span class="tag">${esc(q.section)} · ${q.points} 分</span>${p.original?`<a class="muted" target="_blank" rel="noopener noreferrer" href="${esc(xiaoQuestionPdf(p,q))}">对照原PDF</a>`:''}<button class="btn secondary" id="mark">${state.marks[k]?'取消收藏':'收藏本题'}</button></div><p class="muted">第 ${idx+1} / ${qs.length} 题 · ${esc(q.topic)}${q.type==='multiple'?(p.original?' · 多项选择题':' · 多选，少选、多选、错选均不得分'):''}</p>${q.material?`<details open><summary>阅读材料</summary><div class="material">${esc(q.material)}</div></details>`:''}${allowed?questionSources(q):""}${writingVisual(p,q)}<h2 class="question-title">${esc(q.prompt)}</h2>${q.type==='essay'?`<label for="response" class="muted">你的答案</label><textarea id="response" ${locked?'readonly':''} placeholder="写下你的论点、依据与分析…">${esc(v||'')}</textarea><p class="muted" id="word-count">${countWords(v||'',p.subject)}</p>`:(q.options||[]).map((op,i)=>`<label class="option"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="option" value="${i}" ${Array.isArray(v)&&v.includes(i)?'checked':''} ${locked?'disabled':''}><span>${String.fromCharCode(65+i)}. ${esc(op)}</span></label>`).join('')}<div class="actions"><button class="btn secondary" id="previous" ${idx===0?'disabled':''}>上一题</button><button class="btn" id="next" ${idx===qs.length-1?'disabled':''}>下一题</button>${allowed&&!locked?`<button class="btn secondary" id="reveal">${shown?'收起解析':'查看解析与自评'}</button>`:''}</div></section>${shown?`<section class="card"><h2>${q.type==='essay'?'参考答案与评分要点':correct(a,q)?'回答正确':'核对答案'}</h2>${q.type!=='essay'?`<p><strong>参考答案：${q.answer.map(i=>String.fromCharCode(65+i)).join('、')}</strong> · 本题 ${earned(a,q)} / ${q.points} 分</p>`:''}<div class="answer">${esc(q.explanation)}</div>${q.type==='essay'?`<div class="rubric"><h3>逐项自评 · ${earned(a,q)} / ${q.points} 分</h3><p class="muted">对照自己的答案勾选已充分达到的要点。以下分配是训练用参考量表。</p>${(q.rubric||[]).map((r,i)=>`<label><input type="checkbox" data-rate="${i}" ${(a.ratings[q.id]||[]).includes(i)?'checked':''}><span>${esc(r.text)}（${r.points} 分）</span></label>`).join('')}<button class="btn secondary" id="zero-rating">确认本题自评 0 分</button></div>`:''}</section>`:''}<section class="card"><h3>复盘笔记</h3><textarea id="note" style="min-height:100px" placeholder="错在哪里？下次如何识别？">${esc(state.notes[k]||'')}</textarea></section></div><aside class="sticky"><section class="card"><p class="muted">${locked?'交卷时剩余':'剩余时间'}</p><div class="clock" id="clock">${fmt(remaining(a))}</div>${!locked?`<div class="actions">${a.mode!=='exam'?`<button class="btn secondary" id="timer">${a.deadline?'暂停':'开始计时'}</button>`:'<p class="muted">整卷模式持续计时；离开页面也不会暂停，到时自动交卷。</p>'}</div>`:''}<div class="progress"><i style="width:${ss.done/qs.length*100}%"></i></div><p class="muted">已作答 ${ss.done} / ${qs.length}</p><div class="numbers">${qs.map((it,i)=>`<button title="${esc(it.section)}，${it.points}分" aria-label="第${i+1}题" data-index="${i}" class="${i===idx?'current ':''}${answered(a,it)?'answered ':''}${state.marks[markKey(p,it)]?'marked':''}">${i+1}</button>`).join('')}</div>${!locked?`<div class="actions"><button class="btn warm" id="submit">${p.original?'交卷并保存':'交卷并复盘'}</button></div>`:''}</section></aside></div>`;}


function questionSources(q){
const sources=q.sources||[];if(!sources.length)return '';
return `<details class="question-sources"><summary>材料出处与处理方式</summary><ul>${sources.map(r=>`<li>${r.url&&/^https?:\/\//.test(r.url)?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a>`:esc(r.title)}${r.locator?' · '+esc(r.locator):''}${r.mode?' · '+esc(r.mode):''}</li>`).join('')}</ul></details>`;
}
function chartVisual(c){
const cats=c.categories||[],series=c.series||[],all=series.flatMap(s=>s.values),max=Math.max(...all,1),top=Math.ceil(max/10)*10,colors=['#215c50','#bc7537','#5977a1'];
const cols=cats.length,group=530/cols,bw=Math.min(42,(group-20)/series.length);
return `<svg viewBox="0 0 660 350" role="img" aria-label="${esc(c.title)}" style="width:100%;background:#fafcfb;border:1px solid #dce5e1;border-radius:8px;margin:15px 0"><title>${esc(JSON.stringify(c))}</title><text x="330" y="28" text-anchor="middle" font-size="18">${esc(c.title)}</text>${[0,1,2,3,4,5].map(i=>`<path d="M65 ${265-i*40}H625" stroke="#dce5e1"/><text x="55" y="${270-i*40}" text-anchor="end" font-size="13">${Math.round(top*i/5)}${esc(c.unit||'%')}</text>`).join('')}${cats.map((cat,i)=>`${series.map((se,j)=>{const x=85+i*group+j*bw,h=200*se.values[i]/top;return `<rect x="${x}" y="${265-h}" width="${bw-4}" height="${h}" fill="${colors[j%colors.length]}"/><text x="${x+(bw-4)/2}" y="${258-h}" text-anchor="middle" font-size="13">${se.values[i]}</text>`}).join('')}<text x="${85+i*group+series.length*bw/2}" y="290" text-anchor="middle" font-size="14">${esc(cat)}</text>`).join('')}${series.map((se,i)=>`<rect x="${100+i*180}" y="320" width="15" height="12" fill="${colors[i%colors.length]}"/><text x="${122+i*180}" y="332" font-size="14">${esc(se.name)}</text>`).join('')}</svg>`;
}
function pictureVisual(q){return `<svg viewBox="0 0 720 350" role="img" aria-label="交流，让思考向前：左边学生被隔板分开独自苦思，右边移走隔板一起讨论、记录理由" style="width:100%;background:#fafcfb;border:1px solid #dce5e1;border-radius:8px;margin:15px 0"><g stroke="#173b37" stroke-width="3" fill="none" stroke-linecap="round"><path d="M360 22V295M22 220H338M380 220H698M48 220V265M312 220V265M400 220V265M680 220V265M180 80V245"/><circle cx="80" cy="115" r="22"/><circle cx="280" cy="115" r="22"/><path d="M80 137L92 190L70 220M92 190L120 218M87 158L125 175L139 190M280 137L270 190L290 220M270 190L245 218M277 158L238 175L222 190M115 195H158V212H115ZM112 178H155V193H112ZM116 161H160V176H116ZM204 195H247V212H204ZM208 178H251V193H208ZM204 161H247V176H204Z"/><circle cx="442" cy="115" r="22"/><circle cx="642" cy="115" r="22"/><path d="M442 137L460 191L440 220M460 191L483 219M447 157L493 181L530 196M642 137L626 191L646 220M626 191L603 219M638 157L605 183L579 204M510 192H590V215H510ZM580 191L566 207"/><circle cx="528" cy="202" r="3"/><circle cx="550" cy="202" r="3"/><circle cx="572" cy="202" r="3"/><path d="M531 202H547M553 202H569"/></g><g fill="#173b37" font-size="18" text-anchor="middle"><text x="180" y="42">独自苦思</text><text x="540" y="42">交换理由，共同推进</text><text x="80" y="75" font-size="26">?</text><text x="280" y="75" font-size="26">?</text><text x="360" y="325" font-size="24">交流，让思考向前</text></g></svg>`}

function writingVisual(p,q){
if(p.subject!=='201'||q.points!==20)return '';
if(q.chart)return chartVisual(q.chart);
if(p.id==='201-d')return pictureVisual(q);
if(!['201-a','201-b'].includes(p.id))return '';
if(p.id==='201-b')return `<svg viewBox="0 0 660 340" role="img" aria-label="学生旧物处理方式：2022年闲置50%，丢弃30%，出售或捐赠20%；2026年闲置30%，丢弃20%，出售或捐赠50%" style="width:100%;background:#fafcfb;border:1px solid #dce5e1;border-radius:8px;margin:15px 0"><text x="330" y="30" text-anchor="middle" font-size="19" fill="#173b37">学生旧物处理方式（原创模拟数据）</text><g stroke="#dce5e1"><path d="M65 65H620M65 105H620M65 145H620M65 185H620M65 225H620M65 265H620"/></g><g font-size="13" fill="#657772"><text x="25" y="70">50%</text><text x="25" y="150">30%</text><text x="25" y="230">10%</text><text x="32" y="270">0%</text></g><g fill="#215c50"><rect x="115" y="65" width="40" height="200"/><rect x="285" y="145" width="40" height="120"/><rect x="455" y="185" width="40" height="80"/></g><g fill="#bc7537"><rect x="160" y="145" width="40" height="120"/><rect x="330" y="185" width="40" height="80"/><rect x="500" y="65" width="40" height="200"/></g><g font-size="15" text-anchor="middle" fill="#173b37"><text x="135" y="58">50%</text><text x="180" y="138">30%</text><text x="305" y="138">30%</text><text x="350" y="178">20%</text><text x="475" y="178">20%</text><text x="520" y="58">50%</text><text x="157" y="290">闲置保留</text><text x="327" y="290">直接丢弃</text><text x="497" y="290">出售或捐赠</text></g><rect x="210" y="312" width="16" height="12" fill="#215c50"/><text x="233" y="323" font-size="14">2022年</text><rect x="350" y="312" width="16" height="12" fill="#bc7537"/><text x="373" y="323" font-size="14">2026年</text></svg>`;
return `<svg viewBox="0 0 660 330" role="img" aria-label="拥有与理解：左侧学生拍书堆，笔记空白；右侧学生读一本书并写问题" style="width:100%;background:#fafcfb;border:1px solid #dce5e1;border-radius:8px;margin:15px 0"><g stroke="#173b37" stroke-width="3" fill="none" stroke-linecap="round"><path d="M330 20V280M30 240H305M355 240H630M65 240V275M280 240V275M380 240V275M610 240V275"/><circle cx="105" cy="102" r="23"/><path d="M105 125V200M105 151L145 130L170 110M105 151L146 157L170 125M105 200L85 239M105 200L125 239"/><rect x="168" y="91" width="17" height="35" rx="3"/><path d="M210 220H275V235H210ZM215 199H283V216H215ZM207 177H275V195H207ZM214 155H282V173H214ZM208 133H277V151H208ZM216 111H282V129H216ZM220 88H280V107H220Z"/><path d="M140 222H184V235H140Z"/><circle cx="453" cy="130" r="23"/><path d="M453 153L470 200L455 238M465 177L500 207L520 216M453 171L437 212L420 220M455 238H490L500 273M410 230L440 215L468 231L440 240ZM520 219H570V236H520ZM545 204L532 225"/></g><g font-family="sans-serif" font-size="16" fill="#173b37" text-anchor="middle"><text x="165" y="45">拥有</text><text x="495" y="45">理解</text><text x="330" y="310" font-size="22">拥有与理解</text><text x="540" y="155" font-size="25">?</text></g></svg>`;
}

function countWords(v,s){return s==='201'?`${(v.match(/\b[\w'-]+\b/g)||[]).length} words · ${v.length} 字符`:`${v.replace(/\s/g,'').length} 字`;}
function submit(a){a.remaining=remaining(a);a.deadline=null;a.status='submitted';a.submitted=Date.now();save();if(active?.id===a.id)render();}
function reviewPage(){let rows=[];for(const p of [...BANK,...XIAO8])for(const q of p.questions){const k=markKey(p,q),last=state.attempts.find(a=>a.paper===p.id&&a.bankVersion===2&&a.status==='submitted'&&a.ids.includes(q.id)),wrong=!p.original&&last&&(q.type==='essay'?Object.hasOwn(last.ratings,q.id)&&earned(last,q)<q.points:!correct(last,q));if((filter==='all'&&(state.marks[k]||wrong))||(filter==='wrong'&&wrong)||(filter==='marked'&&state.marks[k]))rows.push({p,q,k,last,wrong});}return `<p class="eyebrow">REVIEW</p><h1>错题与收藏</h1><p class="subtitle">客观题依据最近一次交卷结果归集；主观题仅在你自评后归集。重新答对会自动移出错题。</p><div class="filter"><select id="review-filter"><option value="all" ${filter==='all'?'selected':''}>全部</option><option value="wrong" ${filter==='wrong'?'selected':''}>错题与未得满分</option><option value="marked" ${filter==='marked'?'selected':''}>仅收藏</option></select><input type="search" id="search" placeholder="搜索题干或考点" aria-label="搜索题干或考点"></div><section class="card" id="review-list">${rows.length?rows.map(({p,q,k,wrong})=>`<article class="review-row" data-search="${esc(q.prompt+' '+q.topic)}"><span class="tag">${p.subject} · ${esc(q.topic)}</span><span class="muted">${wrong?'需复习':''}${state.marks[k]?' · 已收藏':''}</span><p>${esc(q.prompt)}</p><button class="btn secondary" data-one="${p.id}" data-q="${esc(q.id)}">重练本题</button></article>`).join(''):'<div class="empty">还没有错题或收藏。完成一套练习，或收藏一道值得再想的题。</div>'}</section>`;}
function historyPage(){return `<p class="eyebrow">LEARNING RECORD</p><h1>练习记录</h1><p class="subtitle">每次练习独立留档。继续未完成答卷，或回看已提交的答案与自评。</p><section class="card scroll">${state.attempts.length?`<table><thead><tr><th>试卷 / 日期</th><th>模式</th><th>进度</th><th>得分</th><th>操作</th></tr></thead><tbody>${state.attempts.map(a=>{const s=summary(a);return `<tr><td>${esc(paper(a.paper).title)}<br><span class="muted">${new Date(a.created).toLocaleString('zh-CN')}</span></td><td>${a.mode==='exam'?'整卷':a.mode==='topic'?'专项':'自由'}</td><td>${s.done}/${a.ids.length} · ${a.status==='submitted'?'已交卷':'未交卷'}</td><td>${paper(a.paper).original?'原卷 · 仅保存作答':a.status==='submitted'?`${s.score}/${s.max}<br>主观自评 ${s.reviewed}/${s.subjective}`:'—'}</td><td><button class="btn secondary" data-resume="${a.id}">${a.status==='submitted'?'回看':'继续'}</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">开始第一套练习，记录会保存在这里。</div>'}</section>`;}
function sourcesPage(){return `<p class="eyebrow">EVIDENCE & BLUEPRINT</p><h1>命题依据与资料</h1><p class="subtitle">参考卷决定结构与能力要求；模拟题、解析和训练量表为本网站原创编制。</p><section class="card"><h2>试卷结构与适用范围</h2><div class="scroll"><table><thead><tr><th>科目</th><th>采用结构</th><th>总分</th></tr></thead><tbody>${Object.entries(SUBJECTS).map(([id,s])=>`<tr><td>${id} ${s.short}</td><td>${s.structure}</td><td>${id==='706'||id==='808'?150:100}</td></tr>`).join('')}</tbody></table></div><p class="note">706以2024—2026回忆材料的80＋70结构命题；2026材料仅列出5道简答，未将缺失题目当成已知。808按近期文学方向的30＋60＋60结构命题，2026文件标作808A且部分分值未列；不能据此断言2027所有方向卷面相同。请以报考方向的正式考试说明为准。</p><p>专业课综合训练覆盖古代文学、现当代文学、语言学、文艺学、古典文献学、古文字学、比较文学与世界文学七个二级学科。“比较文学与世界文学”按本科外国文学范围出题，侧重文学史、作家作品与文本分析。808整卷保留所提供文学方向试卷的重心。</p><p>政治参考PDF为整理版，存在客观题不全的情况；完整模拟卷补齐33道选择题和5道分析题。政治保留思想道德与法治及形势政策范围。</p><p>英语文章为独立撰写的模拟材料，英美刊物提供选题参照，文章不是刊物原文或正式真题。答案与主观评分点用于练习。</p></section>${typeof SOURCE_NOTES!=='undefined'?`<section class="card"><h2>资料读取记录</h2><div class="answer">${esc(SOURCE_NOTES)}</div></section>`:''}${BANK.map(p=>`<section class="card"><span class="tag">${p.subject}</span><h2>${esc(p.title)}</h2><p>${esc(p.basis)}</p><ul>${(p.sources||[]).map(s=>`<li>${s.url&&/^https?:\/\//.test(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}</li>`).join('')}</ul></section>`).join('')}`;}

function hotspotsPage(){return `<p class="eyebrow">101 · 时政与周年专题</p><div class="topline"><h1>从事件找到考点，把原理写进材料。</h1><button class="btn secondary" data-view="subject">返回政治</button></div><p class="subtitle">2026年12月初试 · 依据肖八与已核验官方资料整理。每项按“事件—原理—材料对应—作答”展开。</p><div class="filter"><label>类别 <select id="hotspot-category">${['全部','近期会议','发展规划','周年事件'].map(c=>`<option ${c===hotspotCategory?'selected':''}>${c}</option>`).join('')}</select></label><input id="hotspot-search" type="search" placeholder="搜索事件、教材或原理" aria-label="搜索时政与周年专题"></div><div id="hotspot-items">${HOTSPOTS.filter(h=>hotspotCategory==='全部'||h.category===hotspotCategory).map(h=>{const matches=BANK.filter(p=>p.subject==='101').flatMap(p=>p.questions.filter(q=>h.keywords.some(k=>(q.topic+' '+q.prompt).includes(k))).map(q=>({p,q}))).slice(0,3);return `<article class="card hotspot-item" data-search="${esc(h.title+' '+h.event+' '+h.points.map(p=>p.subject+' '+p.principle+' '+p.application).join(' '))}"><span class="tag">${esc(h.category)}</span><span class="tag">${esc(h.time)}</span><h2>${esc(h.title)}</h2><p>${esc(h.event)}</p><p class="muted">肖八定位：${esc(h.xiao8)}</p><h3>连接的教材考点</h3>${h.points.map(p=>`<div class="hotspot-point"><strong>${esc(p.subject)}</strong><p><b>原理：</b>${esc(p.principle)}<br><b>材料对应：</b>${esc(p.application)}</p></div>`).join('')}<details><summary>可考问法与作答示例</summary><p><strong>${esc(h.angle)}</strong></p><div class="answer">${esc(h.answer)}</div></details><div class="actions"><a href="${esc(h.source)}" target="_blank" rel="noopener noreferrer">查看来源</a>${matches.map(({p,q})=>`<button class="btn secondary" data-one="${p.id}" data-q="${esc(q.id)}">练习：${esc(q.topic)}</button>`).join('')}</div></article>`}).join('')}</div><section class="card"><h2>把四步审题落实到作答</h2><ol><li>读材料，梳理对象、行为、条件与结果。</li><li>读设问，确定学科范围、核心概念和所问关系。</li><li>带着问题回到材料，找到支持原理的关键事实。</li><li>分小问作答：明确判断，阐述原理，结合事实分析，再回应实践要求。</li></ol><p>关键词帮助确定方向，设问范围和材料关系决定主原理。考点材料结合题按“原理—材料—分析”展开；启示题逐点写“行动要求—材料依据—作用”。</p></section>`;}


function xiaoQuestionPdf(p,q){const prefix=location.protocol==='file:'&&decodeURIComponent(location.pathname).endsWith('/四科研习室.html')?'kaoyan-studio/dist/':'';const page=Math.max(1,(q.sourcePages?.[0]||p.pages[0])-p.pages[0]+1);return prefix+'assets/xiao8-'+p.number+'.pdf#page='+page;}
function xiaoShelf(){return `<p class="eyebrow">101 · 肖八原卷</p><div class="topline"><h1>肖八 · 八套逐题练习</h1><button class="btn secondary" data-view="subject">返回政治</button></div><p class="subtitle">每套按1—38题顺序作答：单选、多选、分析题。支持180分钟整卷模拟、自由练习、自动保存和交卷回看。原卷不提供答案、解析和评分。</p><div class="cards">${XIAO8.map(p=>{const last=state.attempts.find(a=>a.paper===p.id&&a.status==='working'),draft=state.xiao8?.[p.id]?.notes;return `<section class="card"><span class="tag">38题 · 100分</span><h2>${esc(p.title)}</h2><p>16道单选 · 17道多选 · 5道分析</p><div class="actions"><button class="btn" data-start="${p.id}" data-mode="exam">整卷模拟</button><button class="btn secondary" data-start="${p.id}" data-mode="practice">自由练习</button>${last?`<button class="btn secondary" data-resume="${last.id}">继续上次</button>`:''}</div>${draft?`<details><summary>此前保存的整卷草稿</summary><div class="answer">${esc(draft)}</div></details>`:''}</section>`}).join('')}</div>`;}
function render(){nav();$('#crumb').textContent=`四科备考 / ${view==='home'?'学习总览':view==='exercise'?SUBJECTS[subject].short:({subject:SUBJECTS[subject].name,review:'错题与收藏',history:'练习记录',sources:'命题依据与资料',hotspots:'政治 · 时政与周年专题',xiao8:'政治 · 肖八原卷',xiao8reader:'政治 · 肖八阅读与作答'}[view]||'')}`;$('#main').innerHTML=view==='home'?home():view==='subject'?subjectPage():view==='exercise'?exercise():view==='review'?reviewPage():view==='history'?historyPage():view==='hotspots'?hotspotsPage():view==='xiao8'?xiaoShelf():sourcesPage();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.subject){subject=b.dataset.subject;show('subject');return;}if(b.dataset.view){show(b.dataset.view);return;}if(b.dataset.start){if(b.dataset.mode==='exam'&&!confirm('开始180分钟整卷计时？计时不会因关闭页面而暂停，交卷前隐藏解析。'))return;start(b.dataset.start,b.dataset.mode);return;}if(b.dataset.resume){resume(b.dataset.resume);return;}if(b.dataset.one){start(b.dataset.one,'topic',[b.dataset.q]);return;}if(b.id==='topic-start'||b.id==='random-start'){const selected=$('#topic').value;const ps=BANK.filter(p=>p.subject===subject);const candidates=ps.flatMap(p=>p.questions.filter(q=>b.id==='random-start'||q.topic===selected).map(q=>({p,q})));if(!candidates.length)return; // Keep attempts tied to one source paper for stable scoring.
 const choice=candidates[Math.floor(Math.random()*candidates.length)],pool=choice.p.questions.filter(q=>b.id==='random-start'||q.topic===selected);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}start(choice.p.id,'topic',pool.slice(0,b.id==='random-start'?5:pool.length).map(q=>q.id));return;}
if(b.id==='export'){download('研习室学习备份.json',JSON.stringify(state,null,2),'application/json');return;}if(!active)return;const qs=questions(active),q=qs[idx],p=paper(active.paper);if(b.dataset.index!==undefined||b.id==='next'||b.id==='previous'){idx=b.dataset.index!==undefined?Number(b.dataset.index):idx+(b.id==='next'?1:-1);active.position=idx;reveal=false;save();render();$('#main').focus();return;}if(b.id==='mark'){const k=markKey(p,q);state.marks[k]=!state.marks[k];save();render();}if(b.id==='reveal'){reveal=!reveal;render();}if(b.id==='timer'){if(active.deadline){active.remaining=remaining(active);active.deadline=null;}else active.deadline=Date.now()+active.remaining*1000;save();render();}if(b.id==='submit'){const n=qs.filter(it=>!answered(active,it)).length;if(confirm(p.original?(n?`还有 ${n} 题未作答。确认交卷并保存？`:'确认交卷并保存？'):(n?`还有 ${n} 题未作答。确认交卷并查看解析？`:'确认交卷并查看解析？')))submit(active);}if(b.id==='zero-rating'){active.ratings[q.id]=[];save();render();}if(b.id==='export-attempt'){const lines=[p.title,new Date(active.created).toLocaleString('zh-CN'),...qs.flatMap((it,i)=>[`${i+1}. ${it.prompt}`,`作答：${Array.isArray(active.answers[it.id])?active.answers[it.id].map(n=>String.fromCharCode(65+n)).join('、'):active.answers[it.id]||'未作答'}`,...(p.original?[]:[`得分：${earned(active,it)}/${it.points}`,`参考：${it.explanation}`]),''])];download('研习室答卷.txt',lines.join('\n'),'text/plain');}});
document.addEventListener('input',e=>{if(e.target.id==='hotspot-search'){const term=e.target.value.toLowerCase();document.querySelectorAll('.hotspot-item').forEach(r=>r.hidden=!r.dataset.search.toLowerCase().includes(term));return;}if(e.target.id==='search'){const term=e.target.value.toLowerCase();document.querySelectorAll('.review-row').forEach(r=>r.hidden=!r.dataset.search.toLowerCase().includes(term));return;}if(!active)return;const q=questions(active)[idx];if(e.target.id==='response'&&active.status!=='submitted'){active.answers[q.id]=e.target.value;$('#word-count').textContent=countWords(e.target.value,paper(active.paper).subject);save();}if(e.target.id==='note'){state.notes[markKey(paper(active.paper),q)]=e.target.value;save();}});
document.addEventListener('change',e=>{if(e.target.id==='hotspot-category'){hotspotCategory=e.target.value;render();return;}if(e.target.id==='review-filter'){filter=e.target.value;render();return;}if(!active)return;const q=questions(active)[idx];if(e.target.name==='option'&&active.status!=='submitted'){active.answers[q.id]=[...document.querySelectorAll('input[name=option]:checked')].map(i=>Number(i.value));save();const y=window.scrollY;render();window.scrollTo(0,y);}if(e.target.dataset.rate!==undefined){const n=Number(e.target.dataset.rate),r=new Set(active.ratings[q.id]||[]);if(e.target.checked)r.add(n);else r.delete(n);active.ratings[q.id]=[...r];save();const y=window.scrollY;render();window.scrollTo(0,y);}});
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('#import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>15e6)throw Error('备份文件过大');const x=JSON.parse(await f.text());if(x.version!==1||!Array.isArray(x.attempts)||!x.marks||!x.notes)throw Error('不是有效的研习室备份');for(const a of x.attempts){const p=a.bankVersion===2?paper(a.paper):(LEGACY_BANK.find(p=>p.id===a.paper)||paper(a.paper));if(!p||!Array.isArray(a.ids)||!a.ids.length||!a.ids.every(id=>p.questions.some(q=>q.id===id))||!a.answers||!a.ratings||!Number.isFinite(a.remaining)||a.remaining<0||!['working','submitted'].includes(a.status)||!['exam','practice','topic'].includes(a.mode)||!Number.isFinite(a.created)||(a.deadline!==null&&!Number.isFinite(a.deadline)))throw Error('答卷数据不匹配');for(const q of p.questions){const v=a.answers[q.id];if(v!==undefined&&(q.type==='essay'?typeof v!=='string':!Array.isArray(v)||v.some(i=>!Number.isInteger(i)||i<0||i>=q.options.length)||new Set(v).size!==v.length))throw Error('答案格式错误');const r=a.ratings[q.id];if(r!==undefined&&(!Array.isArray(r)||new Set(r).size!==r.length||r.some(i=>!Number.isInteger(i)||!q.rubric?.[i])))throw Error('评分格式错误');}}if(!confirm('导入将替换当前浏览器中的练习记录。已导出当前记录时再继续。'))return;state=x;save();show('home');toast('备份已导入');}catch(err){toast('导入失败：'+err.message);}finally{e.target.value='';}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();show('home')});
setInterval(()=>{for(const a of state.attempts){if(a.status==='working'&&a.deadline&&remaining(a)===0){submit(a);toast('时间到，答卷已自动提交');}}if(active&&$('#clock')){$('#clock').textContent=fmt(remaining(active));$('#clock').classList.toggle('urgent',remaining(active)<600);}},1000);
render();



